define(["jquery"],function($){const open=(element,api,item)=>{const button=element.querySelector('[data-action="acknowledge"]');button.addEventListener("click",()=>{button.disabled=true;api.complete({acknowledged:true}).then(result=>{if(result.completed){api.dismiss(true)}else{button.disabled=false}}).catch(()=>{button.disabled=false})},{once:true});if(!item.pause){window.setTimeout(()=>api.dismiss(false),Number(item.data.displayduration||8)*1e3)}};return{open:open}});